// HEC IELTS Speaking & Listening, Year 1, Term 2 (People, places, stories): class plays for
// Sun Class (grades 8-10). Original scripts by the school; no test material, no promise of a band.
import type { Play, PlayLine } from "@/lib/lessonDecks/plays";

const r = (role: string, text: string, d?: string): PlayLine => (d ? { role, text, do: d } : { role, text });
// A group line pinned to one member: the child who holds the letter, the envelope or the basket.
const pin = (role: string, member: number, text: string, d?: string): PlayLine => ({ role, text, member, ...(d ? { do: d } : {}) });
const all = (role: string, text: string, d?: string): PlayLine => ({ role, text, all: true, ...(d ? { do: d } : {}) });
const st = (stage: string, cond?: string): PlayLine => (cond ? { stage, if: cond } : { stage });
const ev = (everyone: string, d?: string): PlayLine => (d ? { everyone, do: d } : { everyone });
// Script, then the teacher's fix, then key words, then no script at all: the last round is the students' own words.
const rh = (read: number, cards: number, free: number, cardWords: string, noScript: string) => [
  { round: "Read-through with scripts", minutes: read, how: "Read the play aloud with parts, standing where the stage directions say. Hidden things stay hidden: nobody looks at another character's letter, envelope, notebook or screen." },
  { round: "Teacher's one-minute fix", minutes: 2, how: "Pick one or two of the fixes from what you just heard. Say the line wrong, then right; the speaker says it again, and the class says the frame in chorus." },
  { round: "Key-word cards, faster", minutes: cards, how: `Scripts down. Each part keeps a card of key words only, and the scene runs again in less time, in the 4/3/2 spirit: same story, fewer seconds. ${cardWords}` },
  { round: "No script: perform and improvise", minutes: free, how: `Every paper away. Play the story from memory in your own words, keeping the frames, then play the improvised scene. ${noScript}` },
];
const mk = (n: number, p: Omit<Play, "id" | "course" | "level" | "unit" | "band">): Play => ({
  id: `hec-ielts-y1-t2-p${n}`, course: "hec-ielts-sl", level: 1, unit: 2, band: "13-16", ...p,
});

